"""Original acid-base chapter: tubular disease, toxins and treatment selection."""
from create_acid_base import rows,q,AC,AL,BI,SA
from qbank_authoring import ref,finalize
RT=ref('ERKNet/ESPN: Distal Renal Tubular Acidosis Clinical Practice Points, 2021','https://academic.oup.com/ndt/article/36/9/1585/6259151')
MT=ref('EXTRIP: Methanol Recommendations','https://www.extrip-workgroup.org/methanol')
EG=ref('EXTRIP: Ethylene Glycol Recommendations, 2023','https://www.extrip-workgroup.org/_files/ugd/4654ea_5fc7a31e85fe4a0da7dfb3f43c9afcaf.pdf')
q('Hypokalemic normal-gap acidosis, recurrent calcium phosphate stones and urine pH persistently above 5.5 during systemic acidosis suggest which disorder?', 'Distal renal tubular acidosis',[
 ('Proximal RTA after bicarbonate has fallen below the reabsorptive threshold','Distal acidification is usually preserved then, allowing a lower urine pH.'),('Type 4 RTA as the best fit','Hyperkalemia is more typical and stone-forming alkaline urine is not its defining feature.'),('Vomiting-induced alkalosis','The systemic disorder is acidosis rather than alkalosis.')],
 'Distal acid secretion failure creates a stone-prone phenotype', '**An inappropriately alkaline urine during metabolic acidosis supports distal RTA.**',['Hypocitraturia and hypercalciuria contribute to stones and nephrocalcinosis.','Exclude urease-producing infection and major confounders.'], '**Treat the acid and potassium deficits and seek the cause.**',['Autoimmune disease such as Sjögren syndrome can cause acquired disease.','Inherited forms can have hearing or other associated abnormalities.'],[['Systemic pattern','Normal-gap acidosis'],['Urine','Inappropriately alkaline'],['Complications','Stones/nephrocalcinosis']],[RT],'clinical_scenario')
q('What happens to urine pH in isolated proximal RTA once plasma bicarbonate falls below the reduced proximal reabsorptive threshold?', 'The intact distal nephron can acidify urine below 5.5',[
 ('Urine must remain above 7 at every plasma bicarbonate','That is not true after the filtered bicarbonate load falls.'),('The disorder necessarily converts into type 4 RTA','Potassium and aldosterone physiology do not automatically change this way.'),('All ammonium excretion stops permanently','Distal acid handling is relatively preserved in isolated proximal disease.')],
 'Bicarbonate wasting depends on the filtered load', '**Proximal reabsorptive capacity is reduced, not necessarily absent.**',['At a lower plasma bicarbonate, less spills into urine.','During alkali administration, bicarbonaturia can again raise urine pH.'], '**Use the full pattern rather than one urine pH.**',['Look for other Fanconi losses.','Large alkali requirements can increase potassium wasting and need monitoring.'],[['Above threshold','Bicarbonaturia/alkaline urine'],['Below threshold','Urine can acidify'],['Other losses','Suggest Fanconi syndrome']],[AC,RT])
q('Normal-gap acidosis occurs with normoglycemic glycosuria, aminoaciduria and phosphate wasting. Which process best explains it?', 'Proximal bicarbonate loss as part of Fanconi syndrome',[
 ('Isolated distal hydrogen secretion failure as the full explanation','It does not explain generalized proximal solute loss.'),('Primary respiratory alkalosis alone','It does not account for the multisubstrate renal losses.'),('Autonomous aldosterone excess','That typically produces alkalosis and hypertension.')],
 'A multi-solute pattern localizes the tubular defect', '**The proximal tubule normally reclaims bicarbonate and several filtered nutrients.**',['Drug toxicity, monoclonal proteins and inherited disease can cause Fanconi syndrome.','Phosphate loss can contribute to osteomalacia.'], '**Remove a treatable driver and replace losses safely.**',['Evaluate exposure history and monoclonal disease where appropriate.','Monitor potassium during alkali therapy.'],[['Site','Proximal tubule'],['Acidosis','Bicarbonate wasting'],['Associated losses','Glucose/phosphate/amino acids']],[AC,RT],'clinical_scenario')
q('Which potassium pattern helps distinguish classic distal or proximal RTA from type 4 RTA?', 'Classic types 1 and 2 are commonly hypokalemic; type 4 is commonly hyperkalemic',[
 ('All forms always have identical potassium values','Potassium patterns are diagnostically useful, though exceptions occur.'),('Type 4 is defined by profound hypokalemia','It is typically hyperkalemic.'),('Potassium alone establishes the complete diagnosis','Clinical context and acid-base assessment remain necessary.')],
 'Potassium and acid secretion are physiologically linked', '**Reduced aldosterone activity and hyperkalemia impair ammonium excretion in type 4 disease.**',['Types 1 and 2 often have renal potassium loss.','Advanced CKD and drugs can blur the textbook patterns.'], '**Interpret with renal function and medication history.**',['Confirm a metabolic normal-gap process.','Exclude extrarenal bicarbonate loss before assigning RTA.'],[['Type 1','Often low potassium'],['Type 2','Often low potassium'],['Type 4','Usually high potassium']],[AC,RT])
q('In normal-gap metabolic acidosis, what does a strongly negative urine anion gap often suggest when no major confounder is present?', 'Increased ammonium chloride excretion, favoring an appropriate renal response such as in diarrhea',[
 ('Direct proof of absent ammonium excretion','A negative value often indicates the opposite.'),('A direct measured ammonium concentration','The urine gap is an indirect surrogate.'),('A universal diagnosis of distal RTA','Distal RTA often has impaired ammonium excretion and a nonnegative gap.')],
 'The urine gap relies on ammonium being accompanied by chloride', '**Urine anion gap = urine sodium + potassium − chloride.**',['High ammonium chloride excretion increases unmeasured urinary cations.','Low distal sodium delivery or nonchloride ammonium salts can make the inference unreliable.'], '**Prefer direct ammonium measurement when available.**',['Use the osmolar gap cautiously as another indirect estimate.','Do not diagnose RTA from the sign alone.'],[['Negative gap','Often high ammonium chloride'],['Positive gap','May reflect impaired ammonium or confounding'],['Best measurement','Direct urine ammonium']],[AC,RT])
q('Why can the urine anion gap mislead during ketoacidosis or toluene exposure?', 'Ammonium may be excreted with nonchloride organic anions',[
 ('Ammonium is necessarily absent in these conditions','It may be appropriately increased.'),('Urine sodium and potassium cannot be measured','The problem is interpretation, not assay impossibility.'),('The urine gap becomes a direct blood pH measurement','It remains an indirect urinary index.')],
 'A surrogate fails when its counterion assumption fails', '**The standard urine-gap inference assumes ammonium chloride excretion.**',['Ketoanions or hippurate can accompany ammonium instead.','A nonnegative gap then need not prove renal acidification failure.'], '**Use direct or alternative assessment and the exposure history.**',['Check serum gap and relevant toxin data.','Avoid reflex labeling as distal RTA.'],[['Assumption','Ammonium paired with chloride'],['Confounder','Organic counterions'],['Result','Potentially misleading urine gap']],[AC])
q('Topiramate is followed by normal-gap acidosis and calcium phosphate stones. Which drug action is most relevant?', 'Carbonic anhydrase inhibition with tubular acid-base effects',[
 ('Direct aldosterone receptor stimulation','This is not the principal mechanism.'),('Increased renal bicarbonate retention without urinary changes','The drug can promote bicarbonate loss and hypocitraturia.'),('Alcohol dehydrogenase inhibition','That describes fomepizole rather than topiramate.')],
 'Some drugs alter both acid balance and stone risk', '**Carbonic anhydrase inhibition can produce a proximal or mixed tubular acidification phenotype.**',['Urine alkalinity and low citrate contribute to calcium phosphate risk.','The severity depends on dose and susceptibility.'], '**Review the medication and alternative treatment.**',['Assess bicarbonate, potassium and stone history.','Do not stop essential therapy without an appropriate replacement plan.'],[['Drug effect','Carbonic anhydrase inhibition'],['Blood','Normal-gap acidosis'],['Urine/stone','Low citrate and calcium phosphate risk']],[AC,RT],'clinical_scenario')
q('What did BICARICU-2 find in critically ill adults with severe metabolic acidemia and moderate-to-severe AKI?', 'Bicarbonate did not significantly reduce 90-day mortality, although KRT use was lower',[
 ('A definitive 90-day mortality reduction in every eligible patient','The primary mortality outcome was not improved.'),('Proof that bicarbonate must never be used for any indication','The trial does not support this blanket conclusion.'),('Evidence that bicarbonate replaces urgent KRT in all refractory cases','Urgent indications still require appropriate support.')],
 'Separate the primary outcome from secondary effects', '**The 2025 trial did not confirm a mortality benefit.**',['KRT initiation was less frequent in the bicarbonate group.','Open-label treatment and KRT decision pathways matter when interpreting that outcome.'], '**Use a selected clinical indication and monitor harms.**',['Sodium load, volume, CO2 generation and ionized calcium changes are relevant.','Treat the underlying cause and do not delay necessary KRT.'],[['Primary endpoint','No significant mortality reduction'],['KRT use','Lower with bicarbonate'],['Clinical implication','Individualized rather than universal therapy']],[BI])
q('Why can giving bicarbonate to a patient with inadequate ventilation be problematic?', 'Buffering generates CO2 that must be eliminated by ventilation',[
 ('Bicarbonate chemically removes all carbon dioxide','It can increase CO2 generation.'),('The treatment has no sodium or volume consequences','Sodium and fluid burdens can be important.'),('Ionized calcium always rises predictably','Alkalinization can lower ionized calcium.')],
 'Buffer delivery does not solve every component of acidemia', '**Generated CO2 can worsen hypercapnia if ventilation is insufficient.**',['The net response depends on circulation, ventilation and the cause.','A laboratory pH rise is not synonymous with a better clinical outcome.'], '**Assess respiratory capacity before and during therapy.**',['Use a monitored indication.','Address severe hypoventilation and the primary disease.'],[['Buffer reaction','CO2 generation'],['Requirement','Adequate CO2 elimination'],['Other risks','Sodium, volume and ionized calcium effects']],[AC,BI])
q('High-gap acidosis and new visual symptoms follow an uncertain solvent ingestion. Which toxin is especially concerning?', 'Methanol',[
 ('Isopropanol as the characteristic cause of formate-mediated visual injury','Isopropanol commonly causes ketosis without the same high-gap formate toxicity.'),('Ethanol alone as the defining cause','Methanol metabolism provides the classic visual-toxic syndrome.'),('A pure chloride-rich saline effect','That does not explain the ingestion and visual findings.')],
 'Toxic metabolites determine organ injury', '**Methanol is metabolized to formate, which causes acidosis and visual toxicity.**',['An elevated osmolal gap may be most evident earlier.','A normal gap does not safely exclude a late presentation.'], '**Start urgent toxicology-directed treatment without awaiting every confirmatory test.**',['Alcohol dehydrogenase blockade and dialysis assessment are central.','EXTRIP includes new visual deficits among strong extracorporeal-treatment indications.'],[['Parent alcohol','Osmolal contribution'],['Metabolite','Formate'],['Organ clue','Visual injury']],[MT],'clinical_scenario')
q('AKI, high-gap acidosis, hypocalcemia and calcium oxalate crystalluria follow antifreeze ingestion. Which agent is most likely?', 'Ethylene glycol',[
 ('Methanol','Visual injury and formate are more characteristic than oxalate nephrotoxicity.'),('Isopropanol','Ketosis without substantial metabolite-driven acidosis is more typical.'),('Acetone alone','This does not fit the oxalate kidney injury pattern.')],
 'Metabolism creates nephrotoxic acids and oxalate', '**Ethylene glycol metabolites cause acidosis and kidney injury.**',['Oxalate binds calcium and can deposit in renal tubules.','Crystals may be absent, so their absence does not exclude poisoning.'], '**Use urgent antidotal and extracorporeal assessment.**',['Fomepizole inhibits alcohol dehydrogenase.','Severity, kidney impairment and metabolite burden guide dialysis selection.'],[['Acidosis','Organic acid metabolites'],['Calcium','May fall'],['Kidney','Oxalate-related injury']],[EG],'clinical_scenario')
q('Why can the osmolal gap be normal late in toxic alcohol poisoning despite severe high-gap acidosis?', 'The parent alcohol has been converted into acid metabolites',[
 ('Normal osmolal gap always excludes methanol or ethylene glycol','It cannot exclude a metabolized late exposure.'),('The acid metabolites never affect the anion gap','They can markedly raise it.'),('The osmolal gap is a direct toxin level','It is an indirect nonspecific estimate.')],
 'Two gaps reflect different phases of metabolism', '**Parent alcohol raises measured osmolality, while accumulating acids raise the anion gap.**',['Ethanol and other osmoles confound estimation.','Baseline gap variation also limits sensitivity.'], '**Use timing and clinical suspicion to guide urgent care.**',['Obtain specific concentrations when available.','Do not withhold antidote solely because one screening index is normal.'],[['Earlier','Parent-alcohol osmolal gap'],['Later','Metabolite anion gap'],['Exclusion','Neither screening gap is definitive']],[MT,EG])
q('A patient with prolonged vomiting has alkalemia, hypokalemia and urine chloride 8 mmol/L before saline or diuretics. Which treatment addresses the maintenance mechanism?', 'Chloride and volume repletion with potassium replacement as appropriate',[
 ('Further gastric suction without replacement','This perpetuates losses.'),('A thiazide to increase chloride depletion','This can worsen the alkalosis and potassium loss.'),('Bicarbonate infusion','This adds alkali to an alkalotic state.')],
 'Generation and maintenance are distinct', '**Gastric acid loss generates alkalosis; chloride and volume depletion sustain renal bicarbonate retention.**',['Hypokalemia also promotes maintenance.','Urine chloride is often below 20 mmol/L in this setting.'], '**Stop ongoing losses and restore the missing components.**',['Fluid selection depends on circulation and comorbidity.','Reassess urine indices after treatment changes.'],[['Generation','Gastric acid loss'],['Maintenance','Chloride/volume and potassium depletion'],['Treatment','Replace deficits and stop losses']],[AL],'clinical_scenario')
q('A patient has metabolic alkalosis and high urine chloride while taking an active loop diuretic. Which interpretation is correct?', 'The diuretic can raise urine chloride despite volume depletion',[
 ('High urine chloride always excludes diuretic-induced depletion','Recent active diuresis is a major confounder.'),('The result proves primary aldosteronism without hormone testing','Hypertension, medications and renin-aldosterone evaluation matter.'),('Urine chloride never changes with treatment timing','It is a dynamic measurement.')],
 'A spot value depends on when the drug was taken', '**Active loop or thiazide therapy increases renal chloride loss.**',['After the effect wears off, urine chloride can fall in a depleted patient.','Repeated measurements and a drug screen can help selected diagnostic problems.'], '**Interpret with blood pressure and medication history.**',['Do not use a single cutoff as an infallible rule.','Review the continuing indication and replacement needs.'],[['Active diuretic','Urine chloride may be high'],['After effect','Can fall with depletion'],['Interpretation','Timing and clinical context']],[AL],'clinical_scenario')
q('Hypertension, hypokalemia and persistent metabolic alkalosis occur with urine chloride above 20 mmol/L. Which pathway should be evaluated?', 'Mineralocorticoid or mineralocorticoid-like sodium-retaining states',[
 ('Remote vomiting as the only possible explanation','The blood pressure and persistent renal chloride pattern favor another pathway.'),('Pure gastrointestinal bicarbonate loss','That typically causes acidosis.'),('Primary respiratory alkalosis as established by chloride alone','A respiratory diagnosis requires PaCO2 assessment.')],
 'Blood pressure helps classify chloride-resistant alkalosis', '**Aldosterone excess, ENaC activation and apparent mineralocorticoid excess can increase distal hydrogen and potassium loss.**',['Renin and aldosterone distinguish mechanisms.','Licorice exposure can inhibit cortisol inactivation and mimic mineralocorticoid activity.'], '**Treat the specific cause.**',['Salt loading alone is not the complete strategy.','Use hormone and genetic evaluation when indicated.'],[['High blood pressure','Sodium-retaining pathway'],['Low potassium','Distal secretion'],['Next tests','Renin/aldosterone and exposure review']],[AL])
q('A patient with heart failure remains fluid overloaded with metabolic alkalosis during necessary loop diuresis. Which adjunct may help selected patients while requiring potassium monitoring?', 'Acetazolamide',[
 ('Large unselected saline loading despite pulmonary congestion','Volume loading can worsen the heart failure.'),('Additional sodium bicarbonate','This adds alkali.'),('Ignore potassium because acetazolamide always raises it','Potassium can fall and requires monitoring.')],
 'A bicarbonaturic drug can help when saline is unsuitable', '**Carbonic anhydrase inhibition increases renal bicarbonate excretion.**',['It is not appropriate for every alkalosis or renal-function context.','Ongoing chloride and potassium balance still matters.'], '**Select the treatment according to congestion and kidney function.**',['Review diuretic intensity and underlying causes.','Monitor acid-base status and electrolytes to avoid overshooting.'],[['Problem','Alkalosis with congestion'],['Possible adjunct','Acetazolamide'],['Monitoring','Potassium, renal function and bicarbonate']],[AL],'clinical_scenario')
q('Hypercalcemia, metabolic alkalosis and AKI develop after heavy calcium carbonate ingestion. Which syndrome is most likely?', 'Calcium-alkali syndrome',[
 ('Tumor lysis syndrome','That typically raises phosphate and lowers calcium.'),('Untreated distal RTA','That produces metabolic acidosis.'),('Isolated chronic respiratory alkalosis','This does not account for the calcium exposure and AKI.')],
 'A combined calcium and alkali load can sustain a vicious cycle', '**Hypercalcemia reduces kidney function and promotes volume depletion, limiting calcium and bicarbonate excretion.**',['Calcium supplements and absorbable alkali are key history items.','Thiazides and CKD can increase susceptibility.'], '**Stop the offending intake and restore appropriate volume.**',['Monitor calcium and renal recovery.','Exclude other hypercalcemic causes if the course is atypical.'],[['Triad','High calcium, alkalosis and AKI'],['Exposure','Calcium plus absorbable alkali'],['Treatment','Stop load and support recovery']],[AL],'clinical_scenario')
q('A short-bowel patient has episodic confusion and ataxia after carbohydrate-rich meals with unexplained high-gap acidosis but normal routine L-lactate. Which diagnosis should be considered?', 'D-lactic acidosis',[
 ('A normal L-lactate excludes all lactate isomer accumulation','Routine assays generally do not measure D-lactate.'),('Pure respiratory acidosis','The gap suggests metabolic acid accumulation.'),('SIAD as the unifying acid-base mechanism','Water retention does not explain this episodic organic acid syndrome.')],
 'An assay may miss the relevant stereoisomer', '**Colonic bacterial carbohydrate fermentation can generate D-lactate in susceptible short-bowel anatomy.**',['Neurological symptoms can accompany acidosis.','The gap can vary with urinary losses and timing.'], '**Request an appropriate specific assay and specialist management.**',['Dietary adjustment and treatment of bacterial production may be needed.','Investigate other causes of altered mental state and acidosis concurrently.'],[['Predisposition','Short bowel with carbohydrate fermentation'],['Assay issue','Normal routine L-lactate'],['Clue','Episodic neurological symptoms']],[AC],'clinical_scenario')

if __name__=='__main__':finalize('Nephrology',9,'Acid-base Disorders','neph-acid-base',rows,36)
